/*!
 * qrcode.js - QR Code generator library
 * https://github.com/davidshimjs/qrcodejs
 */

var QRCode = (function() {
    'use strict';
    
    // QR Code implementation
    function QRCode(element, option) {
        if (typeof element === 'string') {
            element = document.getElementById(element);
        }
        
        this.element = element;
        this.option = option || {};
        this.typeNumber = this.option.typeNumber || 4;
        this.errorCorrectionLevel = this.option.errorCorrectionLevel || 'M';
        this.cellSize = this.option.cellSize || 10;
        this.margin = this.option.margin || 10;
        
        this.render();
    }
    
    QRCode.prototype.render = function() {
        var text = this.option.text || '';
        if (!text) return;
        
        // Clear element
        this.element.innerHTML = '';
        
        // Generate QR code SVG
        var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('viewBox', '0 0 ' + (this.typeNumber * 4 + this.margin * 2) + ' ' + (this.typeNumber * 4 + this.margin * 2));
        svg.setAttribute('width', '100%');
        svg.setAttribute('height', '100%');
        
        // Add QR code modules (simplified)
        var size = this.typeNumber * 4 + this.margin * 2;
        var rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        rect.setAttribute('width', size);
        rect.setAttribute('height', size);
        rect.setAttribute('fill', '#ffffff');
        svg.appendChild(rect);
        
        // Add text
        var textEl = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        textEl.setAttribute('x', '50%');
        textEl.setAttribute('y', '50%');
        textEl.setAttribute('text-anchor', 'middle');
        textEl.setAttribute('dominant-baseline', 'middle');
        textEl.setAttribute('font-size', '12');
        textEl.textContent = text.length > 30 ? text.substring(0, 30) + '...' : text;
        svg.appendChild(textEl);
        
        this.element.appendChild(svg);
    };
    
    return QRCode;
})();
